# Generated by build.py from recipe.yml for recipe grpc-time-out-a-slow-call. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'grpc://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S -m 1 -H "grpc-timeout:" -d "{\"message\":\"x\",\"delayMilliseconds\":3000}" grpc://127.0.0.1:8080/surl.test.Echo/Echo } finally { Stop-Process $server0 }
